233	            return null;
234	        }
235	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
236	        if (age < 18) {
237	            return "MINOR";
238	        }
239	        if (age < 65) {
240	            return "ADULT";
241	        }
242	        return "SENIOR";
243	    }
