394	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
395	     * or null when the {@code customerCode} has not been assigned.
396	     */
397	    public Integer getCheckDigit() {
398	        if (this.customerCode == null) {
399	            return null;
400	        }
401	        int sum = 0;
402	        boolean dbl = true;
403	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
404	            char c = this.customerCode.charAt(i);
405	            if (c < '0' || c > '9') {
406	                continue;
407	            }
408	            int d = c - '0';
409	            if (dbl) {
410	                d *= 2;
411	                if (d > 9) {
412	                    d -= 9;
413	                }
414	            }
415	            sum += d;
416	            dbl = !dbl;
417	        }
418	        return (10 - (sum % 10)) % 10;
